  "data": {
    "name": "Outline",
    "displayName": "Outline",
    "group": "Outline",
    "category": "Navigation",
    "keywords": [
      "outline",
      "table of contents",
      "toc",
      "heading navigation",
      "scroll spy",
      "documentation",
      "anchors",
      "sliding indicator"
    ],
    "playground": {
      "defaults": {
        "items": [
          {
            "id": "overview",
            "label": "Overview",
