            "level": 3
          },
          {
            "id": "api-reference",
            "label": "API reference",
            "level": 2
          }
        ]
      }
    },
    "theming": {
      "targets": [
        {
          "className": "astryx-outline",
          "visualProps": [
            "density"
          ]
        },
        {
          "className": "astryx-outline-indicator"
