          "states": [
            "active"
          ]
        }
      ]
    },
    "components": [
      {
        "name": "Outline",
        "displayName": "Outline",
        "description": "Document outline navigation with sliding indicator track. Renders a flat heading list as anchor links with a density variant and scroll-spy active state when uncontrolled.",
        "props": [
          {
            "name": "items",
            "type": "OutlineItem[]",
            "description": "Ordered heading items. Each item has id, label, and level (1-6). The id should match the target heading element id.",
            "required": true
          },
          {
            "name": "activeId",
            "type": "string",
            "description": "Currently active heading id. Providing this prop makes active state controlled and disables built-in scroll-spy."
          },
          {
            "name": "onActiveIdChange",
            "type": "(id: string) => void",
            "description": "Called when the active item changes from built-in scroll-spy or from an outline link click."
          },
          {
            "name": "label",
            "type": "string",
            "description": "Accessible label for the nav landmark.",
            "default": "'Table of contents'"
          },
          {
            "name": "density",
            "type": "'default' | 'compact'",
            "description": "Density variant controlling item padding. 'compact' for dense UIs, 'default' for standard spacing.",
            "default": "'default'"
          },
          {
            "name": "onNavigateStart",
            "type": "(id: string) => void",
            "description": "Called with the item id when navigation begins, before the scroll starts. Pair with onNavigateEnd to drive an arrival effect (flash, ring, pulse) on the target heading."
          },
          {
            "name": "onNavigateEnd",
            "type": "(id: string) => void",
            "description": "Called with the item id once the navigation resolves - when the smooth scroll settles, or when reduced motion turns it into an instant jump. Fires exactly once per onNavigateStart, including when the user interrupts the scroll, so a \"navigating\" state can never leak."
          },
          {
            "name": "offset",
            "type": "number",
            "description": "Height in px of a fixed header overlaying the top of the scroll root. Shifts both the activation line and the scroll landing by the same amount, so a heading activates exactly where navigating to it puts it - below the header, not underneath it. Composes with each heading's own scroll-margin-top (the header, then the breathing room below it); it does not replace it. Leave at 0 when nothing overlays the content and let scroll-margin-top do the work.",
            "default": "0"
          },
          {
            "name": "scrollContainerRef",
            "type": "React.RefObject<HTMLElement | null>",
            "description": "Scroll container to track, instead of auto-detecting the nearest scrollable ancestor. Use it when content scrolls inside a split pane, modal, or dashboard panel rather than the viewport."
          },
          {
            "name": "hasScrollOnClick",
            "type": "boolean",
            "description": "Whether activating an item smooth-scrolls to it. Set to false to own the scrolling yourself (virtualized content, a router): the Outline still updates the active item, the hash, and the navigate callbacks, but performs no scroll.",
            "default": "true"
          },
          {
            "name": "xstyle",
            "type": "StyleXStyles",
            "description": "StyleX styles for layout customization. Must be a stylex.create() value."
          }
        ],
        "examples": [
          {
            "label": "Basic",
            "code": "\nimport {Outline} from '@astryxdesign/core/Outline';\n\nconst items = [\n  {id: 'overview', label: 'Overview', level: 2},\n  {id: 'installation', label: 'Installation', level: 2},\n  {id: 'theming', label: 'Theming', level: 2},\n  {id: 'tokens', label: 'Tokens', level: 3},\n  {id: 'accessibility', label: 'Accessibility', level: 2},\n];\n\n// Uncontrolled: built-in scroll-spy tracks the topmost visible heading.\n<Outline items={items} />;\n"
          },
          {
            "label": "Compact (density=\"compact\")",
            "code": "\nimport {Outline} from '@astryxdesign/core/Outline';\n\n// Dense sidebars use the compact variant; the sliding indicator\n// automatically matches the shorter item height.\n<Outline items={items} density=\"compact\" />;\n"
          },
          {
            "label": "Controlled active section",
            "code": "\nimport {useState} from 'react';\nimport {Outline} from '@astryxdesign/core/Outline';\n\nfunction ControlledOutline() {\n  const [activeId, setActiveId] = useState('overview');\n\n  // Providing activeId disables built-in scroll-spy; you own the active state.\n  return (\n    <Outline\n      items={items}\n      activeId={activeId}\n      onActiveIdChange={setActiveId}\n    />\n  );\n}\n"
          },
          {
            "label": "Generate items from markdown",
            "code": "\nimport {Markdown} from '@astryxdesign/core/Markdown';\nimport {createMarkdownHeadingLinks} from '@astryxdesign/core/Markdown/plugins';\nimport {Outline, useOutlineFromMarkdown} from '@astryxdesign/core/Outline';\n\nconst markdownRootId = 'guide';\nconst plugins = [\n  createMarkdownHeadingLinks({headingIdPrefix: markdownRootId}),\n];\n\nfunction MarkdownOutline({markdown, isStreaming}) {\n  // Pass the same plugin entry and finality to Markdown and Outline. Nested\n  // headings consume the shared depth-first sequence, while Outline continues\n  // to return root headings only.\n  const items = useOutlineFromMarkdown(markdown, {\n    plugins,\n    isFinal: !isStreaming,\n  });\n  return (\n    <>\n      <Markdown id={markdownRootId} plugins={plugins}>{markdown}</Markdown>\n      <Outline items={items} />\n    </>\n  );\n}\n"
          },
          {
            "label": "Scoped scroll container (split pane, modal, panel)",
            "code": "\nimport {useRef} from 'react';\nimport {Outline} from '@astryxdesign/core/Outline';\n\nfunction PanelDocs() {\n  const scrollContainerRef = useRef(null);\n\n  // Without scrollContainerRef the outline auto-detects the nearest scrollable\n  // ancestor, which is the viewport here - so the highlight would never move.\n  return (\n    <div style={{display: 'flex'}}>\n      <div ref={scrollContainerRef} style={{overflowY: 'auto', height: 480}}>\n        <h2 id=\"overview\">Overview</h2>\n        {/* ...content... */}\n      </div>\n      <Outline items={items} scrollContainerRef={scrollContainerRef} offset={64} />\n    </div>\n  );\n}\n"
          },
          {
            "label": "Navigate callbacks (flash the heading on arrival)",
            "code": "\nimport {useState} from 'react';\nimport {Outline} from '@astryxdesign/core/Outline';\n\nfunction FlashOnArrival() {\n  const [flashId, setFlashId] = useState(null);\n\n  // onNavigateEnd fires once the smooth scroll settles - and once per\n  // onNavigateStart even if the user scrolls away mid-jump, so this never\n  // gets stuck.\n  return (\n    <Outline\n      items={items}\n      onNavigateStart={() => setFlashId(null)}\n      onNavigateEnd={id => setFlashId(id)}\n    />\n  );\n}\n"
          }
        ]
      }
    ],
    "usage": {
      "anatomy": [
        {
          "name": "Outline",
          "required": true,
          "description": "Navigation container for the same-page heading links and indicator."
        },
        {
          "name": "Heading link",
          "required": true,
          "description": "Anchor for one heading, indented by level and marked when active."
        },
        {
          "name": "Label",
          "required": true,
          "description": "Heading text displayed inside its heading link."
        },
        {
          "name": "Indicator track",
          "required": true,
          "description": "Painted vertical rule behind the active indicator."
        },
        {
          "name": "Active indicator",
          "required": true,
          "description": "Sliding bar positioned beside the currently active heading link."
        }
      ],
      "description": "A table-of-contents sidebar for documentation pages, help centers, wikis, and long settings pages. Use it for navigation within a single page, not for app routes. Features a sliding indicator track that animates to the active heading. Each link is in the normal Tab order, and Enter/Space activate.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Pass a flat ordered list of headings and let level control indentation."
        },
        {
          "guidance": true,
          "description": "Use activeId when custom scroll logic owns the active section."
        },
        {
          "guidance": true,
          "description": "Use density=\"compact\" in dense sidebars where vertical space is tight."
        },
        {
          "guidance": true,
          "description": "Use useOutlineFromMarkdown or useOutlineFromDOM when headings are generated from content. For linkable Markdown headings, pass the same createMarkdownHeadingLinks() entry to Markdown and Outline; configure headingIdPrefix on that plugin for multiple roots."
        },
        {
          "guidance": true,
          "description": "Pass scrollContainerRef when the content scrolls in a split pane, modal, or panel instead of the viewport."
        },
        {
          "guidance": true,
          "description": "Set offset to the height of a fixed header that overlays the content, so headings land below it instead of underneath it."
        },
        {
          "guidance": false,
          "description": "Use Outline for application navigation - use SideNav or TopNav for routes."
        },
        {
          "guidance": false,
          "description": "Use Outline for expandable hierarchy - use TreeList when nodes need expand and collapse."
        },
        {
          "guidance": false,
          "description": "Rely on onNavigateEnd to mean \"arrived\" - it also fires when the user interrupts the scroll."
        }
      ]
    },
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/Outline",
    "sourceAvailable": true
  },
